import { Client, Wallet, xrpToDrops, type Payment, type MPTokenAuthorize, type MPTokenIssuanceSet, type MPTokenIssuanceCreate, type Clawback } from 'xrpl'

const client = new Client('wss://s.altnet.rippletest.net:51233')
await client.connect()

const issuerSeed = '<TESTNET_SEED_REDACTED>'
const issuer = Wallet.fromSeed(issuerSeed)

async function submit(wallet: Wallet, tx: any, label: string) {
  try {
    const res = await client.submitAndWait(tx, { wallet })
    const meta = res.result.meta
    const code = meta && typeof meta !== 'string' ? meta.TransactionResult : 'UNKNOWN'
    console.log(`${label}: ${code}`)
    return { ok: code === 'tesSUCCESS', code, res }
  } catch (e: any) {
    console.log(`${label}: THREW ${e?.message ?? e}`)
    return { ok: false, code: 'THREW', res: undefined }
  }
}

const x = Wallet.generate()
const y = Wallet.generate()
console.log('x', x.classicAddress)
console.log('y', y.classicAddress)

await submit(issuer, { TransactionType: 'Payment', Account: issuer.classicAddress, Destination: x.classicAddress, Amount: xrpToDrops('15') } as Payment, 'fund x')
await submit(issuer, { TransactionType: 'Payment', Account: issuer.classicAddress, Destination: y.classicAddress, Amount: xrpToDrops('15') } as Payment, 'fund y')

const create: MPTokenIssuanceCreate = {
  TransactionType: 'MPTokenIssuanceCreate',
  Account: issuer.classicAddress,
  Flags: 0x00000002 | 0x00000004 | 0x00000020 | 0x00000040, // canLock | requireAuth | canTransfer | canClawback
  AssetScale: 0,
  MaximumAmount: '1000000',
}
const createRes = await submit(issuer, create, 'create issuance')
const meta = createRes.res!.result.meta
const issuanceId = meta && typeof meta !== 'string' ? (meta as any).mpt_issuance_id : undefined
console.log('issuanceId', issuanceId)

// x opts in, issuer approves
await submit(x, { TransactionType: 'MPTokenAuthorize', Account: x.classicAddress, MPTokenIssuanceID: issuanceId } as MPTokenAuthorize, 'x opt-in')
await submit(issuer, { TransactionType: 'MPTokenAuthorize', Account: issuer.classicAddress, MPTokenIssuanceID: issuanceId, Holder: x.classicAddress } as MPTokenAuthorize, 'issuer approves x')
// y opts in, issuer approves
await submit(y, { TransactionType: 'MPTokenAuthorize', Account: y.classicAddress, MPTokenIssuanceID: issuanceId } as MPTokenAuthorize, 'y opt-in')
await submit(issuer, { TransactionType: 'MPTokenAuthorize', Account: issuer.classicAddress, MPTokenIssuanceID: issuanceId, Holder: y.classicAddress } as MPTokenAuthorize, 'issuer approves y')

await submit(issuer, { TransactionType: 'Payment', Account: issuer.classicAddress, Destination: x.classicAddress, Amount: { mpt_issuance_id: issuanceId, value: '100' } } as Payment, 'issuer -> x 100')
await submit(issuer, { TransactionType: 'Payment', Account: issuer.classicAddress, Destination: y.classicAddress, Amount: { mpt_issuance_id: issuanceId, value: '100' } } as Payment, 'issuer -> y 100')

// Lock x individually
await submit(issuer, { TransactionType: 'MPTokenIssuanceSet', Account: issuer.classicAddress, MPTokenIssuanceID: issuanceId, Holder: x.classicAddress, Flags: { tfMPTLock: true } } as MPTokenIssuanceSet, 'lock x')

console.log('--- with x locked ---')
await submit(issuer, { TransactionType: 'Payment', Account: issuer.classicAddress, Destination: x.classicAddress, Amount: { mpt_issuance_id: issuanceId, value: '1' } } as Payment, 'issuer -> x (locked) 1')
await submit(x, { TransactionType: 'Payment', Account: x.classicAddress, Destination: issuer.classicAddress, Amount: { mpt_issuance_id: issuanceId, value: '1' } } as Payment, 'x (locked) -> issuer 1')
await submit(x, { TransactionType: 'Payment', Account: x.classicAddress, Destination: y.classicAddress, Amount: { mpt_issuance_id: issuanceId, value: '1' } } as Payment, 'x (locked) -> y 1')
await submit(y, { TransactionType: 'Payment', Account: y.classicAddress, Destination: x.classicAddress, Amount: { mpt_issuance_id: issuanceId, value: '1' } } as Payment, 'y -> x (locked) 1')

// unlock x, revoke auth on y (simulate ban-ish), test receiving while unauthorized
await submit(issuer, { TransactionType: 'MPTokenIssuanceSet', Account: issuer.classicAddress, MPTokenIssuanceID: issuanceId, Holder: x.classicAddress, Flags: { tfMPTUnlock: true } } as MPTokenIssuanceSet, 'unlock x')

console.log('--- with y unauthorized ---')
await submit(issuer, { TransactionType: 'MPTokenAuthorize', Account: issuer.classicAddress, MPTokenIssuanceID: issuanceId, Holder: y.classicAddress, Flags: { tfMPTUnauthorize: true } } as MPTokenAuthorize, 'revoke y auth')
await submit(issuer, { TransactionType: 'Payment', Account: issuer.classicAddress, Destination: y.classicAddress, Amount: { mpt_issuance_id: issuanceId, value: '1' } } as Payment, 'issuer -> y (unauth) 1')
await submit(x, { TransactionType: 'Payment', Account: x.classicAddress, Destination: y.classicAddress, Amount: { mpt_issuance_id: issuanceId, value: '1' } } as Payment, 'x -> y (unauth) 1')
await submit(y, { TransactionType: 'Payment', Account: y.classicAddress, Destination: x.classicAddress, Amount: { mpt_issuance_id: issuanceId, value: '1' } } as Payment, 'y (unauth, still holds 100) -> x 1')

console.log('--- global freeze ---')
await submit(issuer, { TransactionType: 'MPTokenIssuanceSet', Account: issuer.classicAddress, MPTokenIssuanceID: issuanceId, Flags: { tfMPTLock: true } } as MPTokenIssuanceSet, 'global lock')
await submit(issuer, { TransactionType: 'Payment', Account: issuer.classicAddress, Destination: x.classicAddress, Amount: { mpt_issuance_id: issuanceId, value: '1' } } as Payment, 'issuer -> x (global locked) 1')
await submit(x, { TransactionType: 'Payment', Account: x.classicAddress, Destination: issuer.classicAddress, Amount: { mpt_issuance_id: issuanceId, value: '1' } } as Payment, 'x -> issuer (global locked) 1')
await submit(issuer, { TransactionType: 'MPTokenIssuanceSet', Account: issuer.classicAddress, MPTokenIssuanceID: issuanceId, Flags: { tfMPTUnlock: true } } as MPTokenIssuanceSet, 'global unlock')

console.log('--- clawback more than balance ---')
await submit(issuer, { TransactionType: 'Clawback', Account: issuer.classicAddress, Holder: x.classicAddress, Amount: { mpt_issuance_id: issuanceId, value: '999999' } } as Clawback, 'clawback 999999 from x (has ~99)')

const finalX = await client.request({ command: 'ledger_entry', mptoken: { mpt_issuance_id: issuanceId, account: x.classicAddress } })
console.log('final x', JSON.stringify(finalX.result.node))

await client.disconnect()

